"""M11 E3 diagnostic (exploratory, not preregistered): on data generated by the C_res teacher (seed 0), does a
reservoir that shares the teacher's own A and B (seed 0, readout refitted by ridge on the synthetic data) beat
VAR(6)? The preregistered E3 fits reservoirs with seeds 1-3 (not the teacher). A win here means the metric can
see the teacher's class when the class is identified by its recurrent weights; a loss means it cannot even then.
Same synthetic series as E3 (same rng), same metrics. Writes receipts/M11/C/e3_diag/A0x_s{seed}.json.
"""
from __future__ import annotations
import json, time, warnings
from concurrent.futures import ProcessPoolExecutor
import numpy as np
from . import m11_c as C
from .m11_common import write_receipt


def job(args):
    subject, seed = args; warnings.simplefilter("ignore"); t0 = time.time()
    s = C.settings(); gain, port = s["gain"], s["port"]; runs = C.data(subject)["runs"]
    rng = np.random.default_rng(40_000 + subject * 10 + seed)
    teachers = {"a_var6": C.VAR(6).fit(runs[:4]), "b_res": C.Net(C.params(C.new_net(0, port)), gain, port).fit_readout(runs[:4])}
    out = {}
    for name, T in teachers.items():  # identical generation loop to m11_c.e3_job (same rng stream)
        Sigma = np.cov(T.one_step_resid(runs[:4]).T); Lc = np.linalg.cholesky(Sigma + 1e-9 * np.eye(C.N_CH)); syn = []
        for z, ok, *rest in runs:
            st = T.init(z, ok, np.array([max(C.P_GRID)])); xs = np.empty_like(z); xs[:, :max(C.P_GRID) + 1] = z[:, :max(C.P_GRID) + 1]
            for k in range(max(C.P_GRID) + 1, z.shape[1]):
                x = T.predict(st) + rng.normal(size=(1, C.N_CH)) @ Lc.T; xs[:, k] = x[0]; st = T.advance(st, x)
            syn.append((xs, ok, *rest))
        mu = np.hstack([r[0][:, r[1]] for r in syn[:4]]).mean(1, keepdims=True); sd = np.hstack([r[0][:, r[1]] for r in syn[:4]]).std(1, keepdims=True)
        syn = [((x - mu) / sd, ok, *r) for x, ok, *r in syn]
        if name != "b_res": continue
        fits = {"var6": C.VAR(6).fit(syn[:4]), "res_fit_seed": C.Net(C.params(C.new_net(seed + 1, port)), gain, port).fit_readout(syn[:4]),
                "res_teacher_seed": C.Net(C.params(C.new_net(0, port)), gain, port).fit_readout(syn[:4])}
        vr = C.real_val_stats(syn[4:]); fl = C.floor(syn[:4], vr, subject)
        out[name] = {k: {kk: v for kk, v in C.evaluate(m, syn, subject, seed, vr, fl).items() if kk in ("R2_15", "D_gen", "LSD", "LCD", "flags")}
                     for k, m in fits.items()}
    rec = {"stage": "M11", "step": "E3_diag", "exploratory": True, "subject": subject, "seed": seed, **out, "wall_s": time.time() - t0}
    write_receipt(C.OUT / "e3_diag", f"A{subject:02d}_s{seed}", rec, subject=subject, kind="gdf"); return rec


def main():
    with ProcessPoolExecutor(2) as ex:
        for r in ex.map(job, [(s, k) for s in range(1, 10) for k in (0, 1, 2)]):
            print(r["subject"], r["seed"], {k: (round(v["R2_15"], 4), round(v["D_gen"], 3)) for k, v in r["b_res"].items()}, flush=True)


if __name__ == "__main__":
    main()
